array.string:
export PATH="$HOME/.nvm/versions/node/v24.15.0/bin:/usr/local/bin:/usr/bin:/bin" DIR="$HOME/Desktop/벌크농부/00_벌크농부 마케팅 에이전트팀" CFG="$HOME/.config/bulkfarmer/telegram.env" [ -f "$CFG" ] && source "$CFG"
# 알림도 같은 네트워크를 쓴다. 2026-08-11에 초안 생성이 네트워크 때문에 죽었는데 # "실패했다"는 알림조차 못 나갔다. 실패를 알리는 경로는 반드시 재시도한다. notify() { [ -z "$TELEGRAM_BOT_TOKEN" ] && return for n in 1 2 3 4 5; do curl -s -m 20 -X POST "https://api.telegram.org/bot$TELEGRAM_BOT_TOKEN/sendMessage" \ --data-urlencode "chat_id=$TELEGRAM_CHAT_ID" --data-urlencode "text=$1" >/dev/null && return sleep 30 done echo "[$(date +%T)] 텔레그램 알림 실패: $1" >&2 }
cd "$DIR" || { notify "⚠️ 스레드 초안 실패: 폴더 접근 불가"; exit 1; }
TODAY=$(date +%F) OUT="_threads/pending/$TODAY.json"
# 하루에 여러 번 예약돼 있다. 이미 오늘 초안이 있으면 아무것도 하지 않는다. # 08:13에 실패해도 09:33 · 11:13 · 14:13 · 18:13이 남아 있다. [ -s "$OUT" ] && exit 0
PROMPT=$(cat _threads/draft_prompt.txt 2>&1) || { notify "⚠️ 스레드 초안 실패: 프롬프트 읽기 불가 $PROMPT"; exit 1; } command -v claude >/dev/null || { notify "⚠️ 스레드 초안 실패: claude CLI 없음"; exit 1; }
# 맥이 깨어난 직후에는 네트워크가 아직 안 올라와 있다. 2026-08-03 아침에 이 작업과 # 주간 리포트가 같은 이유(ENOTFOUND / Connection closed)로 죽었다. # 2026-08-11에는 40분 넘게 안 올라와 10분 대기로는 모자랐다. 20분으로 늘린다. # 그래도 안 되면 조용히 끝내되, 다음 예약 시각에 다시 시도한다. for i in $(seq 1 80); do curl -s -m 5 -o /dev/null https://api.anthropic.com/ && break sleep 15 done curl -s -m 5 -o /dev/null https://api.anthropic.com/ || { echo "[$(date +%T)] 20분 대기 후에도 네트워크 없음 — 다음 예약에 재시도" >&2; exit 1; }
# API 연결이 응답 도중 끊기는 일이 실제로 있었다(2026-08-03). # 성공 판정은 종료 코드가 아니라 **결과 파일 존재 여부**로 한다 — # 종료 코드가 0이어도 파일이 안 만들어질 수 있다. TRY=0 for TRY in 1 2 3; do [ -s "$OUT" ] && break [ $TRY -gt 1 ] && sleep 90 claude -p "$PROMPT" --model claude-sonnet-5 --permission-mode acceptEdits \ --allowedTools Bash Read Write Edit Glob Grep [ -s "$OUT" ] && break echo "[$(date +%T)] 시도 $TRY 실패" >&2 done
if [ ! -s "$OUT" ]; then H=$(date +%H) # 마지막 예약(18시)까지 실패했을 때만 크게 알린다. 그 전에는 재시도가 남아 있다. if [ "$H" -ge 18 ]; then notify "🚨 스레드 초안 — 오늘 5회 시도 전부 실패했습니다 오늘은 초안이 없습니다. 로그: ~/Library/Logs/bulkfarmer/draft.err.log $(tail -c 300 ~/Library/Logs/bulkfarmer/draft.err.log 2>/dev/null)" else notify "⚠️ 스레드 초안 생성 실패 ($(date +%H:%M)) — 다음 예약 시각에 다시 시도합니다" fi exit 1 fi
N=$(/usr/bin/python3 -c "import json;print(len(json.load(open('$OUT'))['drafts']))" 2>/dev/null || echo "?") if [ "$(date +%H%M)" != "0813" ]; then notify "ℹ️ 스레드 초안 ${N}개 생성 완료 ($(date +%H:%M) 재시도분)" fi exit 0
